-- Route checklist (phase 2). Adds what the automatic checks need. Like the first
-- migration, it only adds new things, because it also runs on the live project.

-- One row per check per revision. The message is what people read, so the app,
-- the dashboard and the contributor all see the same words.
create table public.route_checks (
  route_id text not null references public.transit_routes (id) on delete cascade,
  revision int not null,
  code text not null,
  result text not null check (result in ('pass', 'fail', 'flag', 'skip')),
  message text not null,
  detail jsonb not null default '{}',
  rule_version int not null,
  run_at timestamptz not null default now(),
  primary key (route_id, revision, code)
);

-- The newest row per mode is the one in use. Older rows stay as history.
create table public.fare_rules (
  id bigserial primary key,
  mode text not null check (mode in ('jeepney', 'bus', 'bus_aircon', 'fx_van', 'tricycle')),
  base numeric not null check (base > 0),
  base_km numeric not null check (base_km >= 0),
  per_km numeric not null check (per_km >= 0),
  effective_from date not null default current_date,
  source text not null,
  created_at timestamptz not null default now()
);

create index fare_rules_mode_idx on public.fare_rules (mode, effective_from desc, id desc);

-- Same numbers as lib/services/fare_matrix.dart. They're our own estimates until
-- someone copies the current LTFRB rates in, and the checks say so.
insert into public.fare_rules (mode, base, base_km, per_km, source) values
  ('jeepney', 14, 4, 1.94, 'TransitPH estimate'),
  ('bus', 18, 5, 2.22, 'TransitPH estimate'),
  ('bus_aircon', 18, 5, 3.18, 'TransitPH estimate'),
  ('fx_van', 40, 5, 4.57, 'TransitPH estimate'),
  ('tricycle', 16, 2, 5.33, 'TransitPH estimate');

-- The 4 CAMANAVA cities, from OpenStreetMap borders. Built by
-- tool/route_migration/fetch_service_area.js. If a border doesn't close into a
-- shape, the not-null below stops the whole migration, which is what we want.
create table public.service_areas (
  name text primary key,
  geom extensions.geography(MultiPolygon, 4326) not null
);

insert into public.service_areas (name, geom)
select v.name, extensions.ST_Multi(extensions.ST_BuildArea(extensions.ST_GeomFromText(v.lines, 4326)))::extensions.geography
