-- What share of p_line runs along p_other, in the same direction. It tests 51
-- evenly spaced points, which is plenty for a rule and cheap to run.
create function public.route_line_overlap(p_line extensions.geometry, p_other extensions.geometry) returns numeric
language plpgsql stable
set search_path = extensions, pg_catalog
as $$
declare
  v_matched int;
  v_forward int;
  v_backward int;
begin
  with samples as (
    select i, ST_LineInterpolatePoint(p_line, i / 50.0) as pt
    from generate_series(0, 50) i
  ), near as (
    select i, ST_LineLocatePoint(p_other, pt) as loc
    from samples
    where ST_DWithin(pt::geography, p_other::geography, 30)
  ), steps as (
    select loc, lag(loc) over (order by i) as previous from near
  )
  select count(*),
         count(*) filter (where loc > previous),
         count(*) filter (where loc < previous)
    into v_matched, v_forward, v_backward
    from steps;
  -- The same road the other way is a different route.
  if v_backward > v_forward then return 0; end if;
  return round(v_matched / 51.0, 3);
end;
$$;

-- What share of p_line is within reach of p_other, in either direction.
create function public.route_line_near(p_line extensions.geometry, p_other extensions.geometry) returns numeric
language sql stable
set search_path = extensions, pg_catalog
as $$
  select round(count(*) / 51.0, 3)
  from generate_series(0, 50) i
  where ST_DWithin(ST_LineInterpolatePoint(p_line, i / 50.0)::geography, p_other::geography, 30)
$$;

-- The map questions the checks ask, all answered in one call. Only routes-api
-- calls this. Any part it can't answer comes back null, and the check then sends
-- the route to a moderator instead of passing it.
create function public.route_geometry_facts(
  p_route_id text,
  p_contributor text,
  p_geom text,
  p_correction_of text
) returns jsonb
language plpgsql stable
set search_path = extensions, pg_catalog
as $$
declare
  v_line geometry;
  v_is_gtfs boolean := p_correction_of like 'gtfs:%';
  v_target_exists boolean;
  v_target_status text;
  v_target geography;
  v_length_km numeric;
  v_camanava_km numeric;
  v_published jsonb;
  v_gtfs jsonb;
  v_repeat jsonb;
  v_kept numeric;
begin
  if p_correction_of is not null and p_correction_of <> '' then
    if v_is_gtfs then
      if to_regclass('gtfs.routes') is null then
        v_target_exists := null;
      else
        select exists (
          select 1 from gtfs.routes where route_id = substr(p_correction_of, 6)
        ) into v_target_exists;
      end if;
      v_target_status := case when v_target_exists then 'published' end;
    else
      select status::text, geom into v_target_status, v_target
        from public.transit_routes where id = p_correction_of;
      v_target_exists := found;
    end if;
  end if;

  if p_geom is not null then
    v_line := ST_GeomFromEWKT(p_geom);
    v_length_km := round((ST_Length(v_line::geography) / 1000)::numeric, 2);

    select round((coalesce(sum(ST_Length(ST_Intersection(v_line, a.geom::geometry)::geography)), 0) / 1000)::numeric, 2)
      into v_camanava_km
      from public.service_areas a;

    -- The closest published route, leaving out the route itself and its target.
    select jsonb_build_object(
             'id', c.id,
             'name', coalesce(c.data->>'startLocation', '?') || ' to ' || coalesce(c.data->>'endLocation', '?'),
             'source', c.source,
             'fraction', c.fraction)
      into v_published
      from (
        select r.id, r.data, r.source, public.route_line_overlap(v_line, r.geom::geometry) as fraction
        from public.transit_routes r
        where r.status = 'published'
          and r.geom is not null
          and r.id <> p_route_id
          and r.id is distinct from p_correction_of
          and ST_DWithin(r.geom, v_line::geography, 30)
      ) c
      order by c.fraction desc
      limit 1;

    -- The contributor's own recent or moderator-rejected routes. A route the
    -- system rejected doesn't count: fixing and resending it is what we want.
    if p_contributor is not null then
      select jsonb_build_object('id', c.id, 'fraction', c.fraction, 'status', c.status)
        into v_repeat
        from (
          select r.id, r.status, public.route_line_overlap(v_line, r.geom::geometry) as fraction
          from public.transit_routes r
          where r.contributor_id = p_contributor
            and r.geom is not null
            and r.id <> p_route_id
            and r.id is distinct from p_correction_of
            and (r.status = 'rejected' or r.created_at > now() - interval '7 days')
            and coalesce((
              select d.decision from public.route_decisions d
              where d.route_id = r.id
              order by d.id desc limit 1
            ), '') <> 'auto_rejected'
            and ST_DWithin(r.geom, v_line::geography, 30)
        ) c
        order by c.fraction desc
        limit 1;
    end if;

    -- How much of the target a correction leaves in place.
    if v_target is not null then
      v_kept := public.route_line_near(v_target::geometry, v_line);
    end if;

    -- The GTFS feed has almost no shapes, so compare stops instead. A trip counts
    -- when it stops along the line in order, without skipping most of its stops.
    if to_regclass('gtfs.stop_times') is not null and not coalesce(v_is_gtfs, false) then
      with near_stops as (
        select s.stop_id,
               ST_LineLocatePoint(v_line, ST_SetSRID(ST_MakePoint(s.stop_lon, s.stop_lat), 4326)) as loc
        from gtfs.stops s
        where s.stop_lat between ST_YMin(v_line) - 0.001 and ST_YMax(v_line) + 0.001
          and s.stop_lon between ST_XMin(v_line) - 0.001 and ST_XMax(v_line) + 0.001
          and ST_DWithin(ST_SetSRID(ST_MakePoint(s.stop_lon, s.stop_lat), 4326)::geography, v_line::geography, 60)
      ), visits as (
        select st.trip_id, st.stop_sequence, n.loc,
               lag(n.loc) over (partition by st.trip_id order by st.stop_sequence) as previous
        from gtfs.stop_times st
        join near_stops n on n.stop_id = st.stop_id
      ), trips as (
        select v.trip_id,
               count(*) as matched,
               max(v.stop_sequence) - min(v.stop_sequence) + 1 as spanned,
               count(*) filter (where v.loc > v.previous) as forward,
               count(*) filter (where v.loc < v.previous) as backward,
               max(v.loc) - min(v.loc) as coverage
        from visits v
        group by v.trip_id
      )
      select jsonb_build_object(
               'id', t.route_id,
               'name', coalesce(nullif(r.route_long_name, ''), nullif(r.route_short_name, ''), t.route_id),
               'source', 'gtfs',
               'fraction', round(c.coverage::numeric, 3))
        into v_gtfs
        from trips c
        join gtfs.trips t on t.trip_id = c.trip_id
        left join gtfs.routes r on r.route_id = t.route_id
        where c.matched >= 3
          and c.forward > c.backward
          and c.matched::numeric / c.spanned >= 0.6
        order by c.coverage desc
        limit 1;
    end if;
  end if;

  return jsonb_build_object(
    'target_exists', v_target_exists,
    'target_status', v_target_status,
    'length_km', v_length_km,
    'camanava_km', v_camanava_km,
    'published_overlap', v_published,
    'gtfs_overlap', v_gtfs,
    'repeat', v_repeat,
    'correction_kept', v_kept
  );
end;
$$;

-- Who can do what, the same way as the first migration.

alter table public.route_checks enable row level security;
alter table public.fare_rules enable row level security;
alter table public.service_areas enable row level security;

-- The app reads fares directly, and they aren't private.
create policy public_read on public.fare_rules for select to anon, authenticated using (true);

revoke all on public.route_checks, public.fare_rules, public.service_areas from anon, authenticated;
revoke all on sequence public.fare_rules_id_seq from anon, authenticated;
grant select on public.fare_rules to anon, authenticated;

grant all on public.route_checks, public.fare_rules, public.service_areas to service_role;
grant all on sequence public.fare_rules_id_seq to service_role;

revoke execute on function public.route_line_overlap(extensions.geometry, extensions.geometry) from public, anon, authenticated;
revoke execute on function public.route_line_near(extensions.geometry, extensions.geometry) from public, anon, authenticated;
revoke execute on function public.route_geometry_facts(text, text, text, text) from public, anon, authenticated;

grant execute on function public.route_line_overlap(extensions.geometry, extensions.geometry) to service_role;
grant execute on function public.route_line_near(extensions.geometry, extensions.geometry) to service_role;
grant execute on function public.route_geometry_facts(text, text, text, text) to service_role;
